/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Matrix-Vector Transpose (MVT) kernel.
# Computes, for 0 <= i < n:
#   x1[i] += sum_j A[i, j] * y_1[j]
#   x2[i] += sum_j A[j, i] * y_2[j]
#
# The second matvec is written in an equivalent but more cache-friendly
# form that only accesses A row-major:
#   x2[j] += sum_i A[i, j] * y_2[i]
@proc
def kernel_mvt(
    n: size,
    x1: DATA_TYPE[n] @ DRAM,
    x2: DATA_TYPE[n] @ DRAM,
    y_1: DATA_TYPE[n] @ DRAM,
    y_2: DATA_TYPE[n] @ DRAM,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # First matrix-vector product: x1 += A * y_1
    for i in seq(0, n):
        for j in seq(0, n):
            x1[i] += A[i, j] * y_1[j]

    # Second matrix-vector product: x2 += A^T * y_2
    # Original mathematical definition:
    #   x2[i] += sum_j A[j, i] * y_2[j]
    # Equivalent reformulation with row-major A access:
    #   x2[j] += sum_i A[i, j] * y_2[i]
    for i in seq(0, n):
        for j in seq(0, n):
            x2[j] += A[i, j] * y_2[i]

# ------------------------
# Scheduling / Optimization
# ------------------------

# Start from the base kernel.
p = kernel_mvt

# Tile the inner j-loop of the first matvec to improve cache locality
# for A and y_1 and to expose unrolling / vectorization opportunities.
# Tile size 32 is a reasonable default for modern x86 cores and can be
# adjusted if needed.
p = divide_loop(p, "j", 32, ["jo1", "ji1"])

# Tile the inner j-loop of the second matvec similarly. After the
# previous transformation, the only remaining 'j' loop is in the
# second matvec, so this applies there.
p = divide_loop(p, "j", 32, ["jo2", "ji2"])

# Unroll the innermost tile loops. These loops have constant trip count
# (32) after divide_loop, so full unrolling is safe and improves ILP.
p = unroll_loop(p, "ji1")
p = unroll_loop(p, "ji2")

# Parallelize the outermost i-loop of the first matvec.
# Each iteration writes a distinct x1[i] and only reads A and y_1,
# so iterations are independent and safe to parallelize.
i_outer = p.find_loop("i")
p = parallelize_loop(p, i_outer)

# Perform expression and control-flow simplifications on the scheduled kernel.
kernel_mvt = simplify(p)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A,   DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x1,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x2,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_2, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten PolyBench views to 1D pointers. */
  kernel_mvt(/*ctxt=*/NULL, n,
             (DATA_TYPE*)POLYBENCH_ARRAY(x1),
             (DATA_TYPE*)POLYBENCH_ARRAY(x2),
             (DATA_TYPE*)POLYBENCH_ARRAY(y_1),
             (DATA_TYPE*)POLYBENCH_ARRAY(y_2),
             (DATA_TYPE*)POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n,
                                    POLYBENCH_ARRAY(x1),
                                    POLYBENCH_ARRAY(x2)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x1);
  POLYBENCH_FREE_ARRAY(x2);
  POLYBENCH_FREE_ARRAY(y_1);
  POLYBENCH_FREE_ARRAY(y_2);

  return 0;
}
