from exo import *
from exo.libs.memories import DRAM

# Scheduling primitives and standard library helpers.
from exo.API_scheduling import *
from exo.stdlib.stdlib import tile_loops, vectorize


# Baseline MVT kernel:
#   x1[i] += sum_j A[i, j] * y_1[j]
#   x2[i] += sum_j A[j, i] * y_2[j]
#
# We write it in a cache–friendly way:
# - First matvec: iterate rows of A (i outer, j inner).
# - Second matvec: also iterate rows of A by making j the outer loop and
#   i2 the inner loop. This turns the original column-wise access into
#   a row-wise traversal while preserving the mathematical result.
@proc
def kernel_mvt_base(
    n: size,
    x1: DATA_TYPE[n] @ DRAM,
    x2: DATA_TYPE[n] @ DRAM,
    y_1: DATA_TYPE[n] @ DRAM,
    y_2: DATA_TYPE[n] @ DRAM,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # First matrix-vector product: x1[i] += A[i, j] * y_1[j]
    for i in seq(0, n):
        # Accumulator kept in a scalar to reduce repeated loads/stores of x1[i].
        acc1: DATA_TYPE
        acc1 = x1[i]
        for j in seq(0, n):
            acc1 += A[i, j] * y_1[j]
        x1[i] = acc1

    # Second matrix-vector product:
    # original: for i: for j: x2[i] += A[j, i] * y_2[j]
    # rewritten: for j: for i2: x2[i2] += A[j, i2] * y_2[j]
    # This keeps accesses to A row-major (j is row index) and reuses y_2[j]
    # via a scalar temporary.
    for j in seq(0, n):
        t2: DATA_TYPE
        t2 = y_2[j]
        for i2 in seq(0, n):
            x2[i2] += A[j, i2] * t2


# Apply scheduling to obtain an optimized kernel matching the C name
# expected by the driver.
kernel_mvt = rename(kernel_mvt_base, "kernel_mvt")

# --- Scheduling for the first matvec (x1 update) ---

# Parallelize the outer i-loop: iterations over i are independent
# (each iteration touches a distinct x1[i]).
kernel_mvt = parallelize_loop(kernel_mvt, "i")

# Tile and unroll the inner j-loop of the first matvec to improve
# cache locality on y_1 and A[i, :] and to expose ILP/SIMD.
# We split j into (j_outer, j_inner) with a small constant tile size,
# then fully unroll j_inner.
J_TILE = 8
kernel_mvt = divide_loop(kernel_mvt, "j", J_TILE, ("j_outer", "j_inner"), tail="guard")
kernel_mvt = unroll_loop(kernel_mvt, "j_inner")

