# For the second matvec we already have row-major traversal over A by
# iterating j over rows and i2 over columns. We keep j sequential
# because each j-iteration contributes to all x2[i2] (a reduction over j),
# but we can still increase ILP inside the inner i2-loop.

I2_TILE = 8
kernel_mvt = divide_loop(kernel_mvt, "i2", I2_TILE, ("i2_outer", "i2_inner"), tail="guard")
kernel_mvt = unroll_loop(kernel_mvt, "i2_inner")

# Optionally simplify the resulting IR (constant folding, dead-code elim).
kernel_mvt = simplify(kernel_mvt)
