#   x1[i] += sum_j A[i,j] * y_1[j]
#   x2[i] += sum_j A[j,i] * y_2[j]   (i.e., x2 = x2 + A^T * y_2)
#
# We fuse the two matrix-vector products so that each A[i,j] element is
# loaded only once and used for both updates:
#
#   for i:
#     for j:
#       x1[i] += A[i,j] * y_1[j]
#       x2[j] += A[i,j] * y_2[i]
