#   x2[i] += sum_j A[j,i] * y_2[j]
# The accumulation into x1[i] and x2[i] is done via scalars to
# minimize repeated memory traffic on x1/x2.
@proc
def kernel_mvt_base(
    n: size,
    x1: DATA_TYPE[n] @ DRAM,
    x2: DATA_TYPE[n] @ DRAM,
    y_1: DATA_TYPE[n] @ DRAM,
    y_2: DATA_TYPE[n] @ DRAM,
    A: DATA_TYPE[n, n] @ DRAM,
):
    assert n >= 1

    # First matrix-vector product: x1 = x1 + A * y_1
    for i in seq(0, n):
        acc1: DATA_TYPE
        acc1 = x1[i]
        for j in seq(0, n):
            acc1 += A[i, j] * y_1[j]
        x1[i] = acc1

    # Second matrix-vector product with the transposed matrix:
    # x2 = x2 + A^T * y_2
    for i in seq(0, n):
        acc2: DATA_TYPE
        acc2 = x2[i]
        for j in seq(0, n):
            acc2 += A[j, i] * y_2[j]
        x2[i] = acc2


