# Scheduling / optimization
# -------------------------

kernel_mvt_sched = kernel_mvt_base

# Tile and unroll the inner j-loop of the first matrix-vector product.
# This improves instruction-level parallelism and reduces loop overhead
# without changing the order in which elements are processed.
kernel_mvt_sched = divide_loop(kernel_mvt_sched, "j", 4, ("jo", "ji"), tail="guard")
kernel_mvt_sched = unroll_loop(kernel_mvt_sched, "ji")

